import numpy as np
from scipy.optimize import minimize_scalar
def build(w):
    cols=[np.ones_like(t),x,v,v*v,v**3,x*x]
    for m in [1,2]:
        Cm=np.cos(m*w*t); Sm=np.sin(m*w*t)
        for g in [np.ones_like(t),x,v,v*v]:
            cols+= [g*Cm,g*Sm]
    return np.column_stack(cols)
def f(w):
    A=build(w); c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None); return np.sum((dv_dt-A@c)**2)
